    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rows, cols = set(), set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                if c in (0, w - 1): rows.add(r)
                if r in (0, h - 1): cols.add(c)
    hit = {(r, c) for r in rows for c in range(w)} | {(r, c) for c in cols for r in range(h)}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen: continue
            stack, component = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy in range(y-1, y+2):
                    for xx in range(x-1, x+2):
                        if (yy, xx) == (y, x): continue
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                continue
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if any(cell in hit for cell in component):
                for y, x in component: out[y][x] = 1
    for r, c in hit: out[r][c] = 1
    return out

