def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_marks, col_marks = {}, {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                if c in (0, w - 1): row_marks.setdefault(r, set()).add(c)
                if r in (0, h - 1): col_marks.setdefault(c, set()).add(r)
    hit = set()
    for r, ends in row_marks.items():
        if len(ends) == 2:
            hit.update((r, c) for c in range(w))
        else:
            c = next(iter(ends)); step = 1 if c == 0 else -1
            hit.add((r, c))
            while 0 <= c + step < w:
                c += step; hit.add((r, c))
                if grid[r][c] == 2:
                    while 0 <= c + step < w and grid[r][c + step] == 2:
                        c += step; hit.add((r, c))
                    break
    for c, ends in col_marks.items():
        if len(ends) == 2:
            hit.update((r, c) for r in range(h))
        else:
            r = next(iter(ends)); step = 1 if r == 0 else -1
            hit.add((r, c))
            while 0 <= r + step < h:
                r += step; hit.add((r, c))
                if grid[r][c] == 2:
                    while 0 <= r + step < h and grid[r + step][c] == 2:
                        r += step; hit.add((r, c))
                    break
    rows, cols = {r for r in row_marks}, {c for c in col_marks}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen: continue
            stack, component = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            minx = min(x for y, x in component); maxx = max(x for y, x in component)
            miny = min(y for y, x in component); maxy = max(y for y, x in component)
            horizontal_cross = any(y in rows for y, x in component)
            vertical_cross = any(x in cols and minx < x < maxx for y, x in component)
            if horizontal_cross or vertical_cross:
                for y, x in component: out[y][x] = 1
    for r, c in hit: out[r][c] = 1
    return out
